def HasDensity (s : Set Nat) (δ : ℝ) : Prop :=
  Filter.Tendsto (fun (n : Nat) => ((s ∩ Set.Iio n).ncard : ℝ)) Filter.atTop (nhds δ)

def ProductMap (d : Nat → Nat) (p : Nat × Nat) : Nat :=
  ∏ i ∈ Finset.Icc p.1 p.2, d i

